mapper.select:
SELECT PC AS pc, NUM AS num, MARKET AS market, VARIABLE AS variable, VAL AS val, VS AS vs, VS2 AS vs2, COMMENTS AS comments, ADD_DATE AS addDate, DELETE_DATE AS deleteDate, REGISTER_USER AS registerUser, REGISTER_DATETIME AS registerDatetime FROM HDOC_USER_DEFINED_RULES
AND PC = #{productClass}
AND NUM = #{number}
AND MARKET = #{market}
AND VARIABLE LIKE CONCAT('%', #{variable}, '%')
AND VAL LIKE CONCAT('%', #{value}, '%')
AND VS LIKE CONCAT('%', #{variantString1}, '%')
AND VS2 LIKE CONCAT('%', #{variantString2}, '%')
AND COMMENTS LIKE CONCAT('%', #{comments}, '%')
ORDER BY PC, NUM, MARKET

SELECT COUNT(1)
FROM HDOC_USER_DEFINED_RULES
WHERE PC = #{pc}
  AND NUM = #{num}
  AND MARKET = #{market}

mapper.delete:
DELETE FROM HDOC_USER_DEFINED_RULES
WHERE PC = #{pc}
  AND NUM = #{num}
  AND MARKET = #{market}
